        FROM tb_ai_log_module_config config
        INNER JOIN tb_ai_log_error_event event
            ON event.environment = config.environment
            AND event.system_code = config.system_code
            AND event.module_code = config.module_code
            AND config.enabled = 1

    FROM tb_ai_log_error_event event

WHERE event.issue_group_id IS NOT NULL
  AND event.log_date BETWEEN #{filter.startDate} AND #{filter.endDate}
AND event.environment = #{filter.environment}
AND event.system_code = #{filter.systemCode}
AND event.module_code = #{filter.moduleCode}
